-- persons 表清理 B1 —— 精簡版(對照表 + 5 句 DML)
-- 由 2026-10-03_person_cleanup_B1.sql 原樣轉寫,B 949 組、C 337 列,內容完全相同。
--
-- ★★ 跑法:Navicat「新增查詢」→ 檔案 → 開啟本檔 → 執行(不要用「執行 SQL 檔案」,
--    那個模式看不到結果)。整檔一次跑完,最後兩句 SELECT 會出結果格。
-- ★★ 跑完**先不要 COMMIT**。看最後一句的數字:
--      persons      36883 → 35934(整整少 949)
--      book_persons 81040 → 少一點點(重複關聯撞 uq_book_person_role,被 CASCADE 清掉)
--    數字對了,在**同一個查詢視窗**手動下 COMMIT;  不對就 ROLLBACK;
--
-- ★★ 防呆:三句 DML 都 JOIN 了一個檢查碼子查詢。對照表的筆數或內容只要少一筆、
--    錯一個數字,檢查碼就對不上,JOIN 不成立 → **一列都不會動**(Affected rows 0)。
--    這是刻意的:貼錯的 SQL 不報錯、照樣執行,是最危險的一種失敗。

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS pn_merge;
CREATE TEMPORARY TABLE pn_merge  (src INT PRIMARY KEY, dst INT NOT NULL);
DROP TEMPORARY TABLE IF EXISTS pn_rename;
CREATE TEMPORARY TABLE pn_rename (id  INT PRIMARY KEY, nm VARCHAR(255) NOT NULL);

-- B 對照表 第 1/5 批

-- B 對照表 第 2/5 批

-- B 對照表 第 3/5 批

-- B 對照表 第 4/5 批

-- B 對照表 第 5/5 批

-- C 對照表 第 1/2 批

-- C 對照表 第 2/2 批

-- ═══ 對照表自檢(給人看的;DML 自己也會再檢查一次)═══
SELECT (SELECT COUNT(*) FROM pn_merge)  AS merge_rows,   -- 應 949
       (SELECT SUM(src)  FROM pn_merge) AS merge_sum_src,-- 應 27549840
       (SELECT SUM(dst)  FROM pn_merge) AS merge_sum_dst,-- 應 25384275
       (SELECT COUNT(*)  FROM pn_rename) AS rename_rows, -- 應 337
       (SELECT SUM(id)   FROM pn_rename) AS rename_sum_id,-- 應 10349424
       (SELECT SUM(CHAR_LENGTH(nm)) FROM pn_rename) AS rename_sum_len; -- 應 2025

-- ═══ B. 併入既有正規列(949 組)═══
UPDATE IGNORE book_persons bp
  JOIN pn_merge m ON bp.person_id = m.src
  JOIN (SELECT COUNT(*) c, SUM(src) s1, SUM(dst) s2 FROM pn_merge) g
    ON g.c = 949 AND g.s1 = 27549840 AND g.s2 = 25384275
   SET bp.person_id = m.dst;

DELETE p FROM persons p
  JOIN pn_merge m ON p.person_id = m.src
  JOIN (SELECT COUNT(*) c, SUM(src) s1, SUM(dst) s2 FROM pn_merge) g
    ON g.c = 949 AND g.s1 = 27549840 AND g.s2 = 25384275;

-- ═══ C. 剝乾淨但沒有既有正規列,直接改名(337 列)═══
UPDATE persons p
  JOIN pn_rename r ON p.person_id = r.id
  JOIN (SELECT COUNT(*) c, SUM(id) s1, SUM(CHAR_LENGTH(nm)) s2 FROM pn_rename) g
    ON g.c = 337 AND g.s1 = 10349424 AND g.s2 = 2025
   SET p.name = r.nm;

-- ═══ 回查 ═══
SELECT (SELECT COUNT(*) FROM persons)      AS persons_total,      -- 應 35934
       (SELECT COUNT(*) FROM book_persons) AS book_persons_total; -- 應 < 81040
